def steel_constituents(c):
    a, e, cm = 0.022, 0.76, 6.70
    if not a <= c <= 2.14:
        raise ValueError("not a steel: carbon must be between 0.022 and 2.14 wt%")
    if c <= e:
        pearlite = (c - a) / (e - a)
        return "ferrite", 1 - pearlite, pearlite
    pearlite = (cm - c) / (cm - e)
    return "cementite", 1 - pearlite, pearlite

import math

def miscibility_gap(W, T, R=8.314):
    if T >= W / (2 * R):
        return None
    lo, hi = 1e-15, 0.5 - 1e-12
    for _ in range(200):
        mid = (lo + hi) / 2
        slope = W * (1 - 2 * mid) + R * T * math.log(mid / (1 - mid))
        if slope > 0:
            hi = mid
        else:
            lo = mid
    x = (lo + hi) / 2
    return x, 1 - x
